CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_user`(
    IN _dsId       VARCHAR(50),
    IN _dsUsuario  VARCHAR(50),
    IN _pass       VARCHAR(100),
    IN _creadoPor  VARCHAR(50))
BEGIN
    DECLARE v_salt VARBINARY(16);
    SET v_salt = RANDOM_BYTES(16);

    INSERT INTO usuarios (dsId, dsUsuario, dsPassword, dsSalt, dsEstado, dsUsuarioCreacion)
    VALUES (_dsId, _dsUsuario,
            UNHEX(SHA2(CONCAT(v_salt, _pass), 512)),
            v_salt, '1', _creadoPor);
END ;;
DELIMITER ;
