CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ResumenUsuarios`()
BEGIN
    SELECT COUNT(*)                                   AS Total,
           CAST(IFNULL(SUM(dsEstado = '1'), 0) AS UNSIGNED) AS Activos
    FROM usuarios;
END ;;
