/*!50003 DROP PROCEDURE IF EXISTS `sp_ValidarLoginHash` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ValidarLoginHash`(
    IN _dsUsuario  VARCHAR(50)  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
    IN _dsPassword VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
)
BEGIN
    DECLARE v_id   INT DEFAULT NULL;
    DECLARE v_salt VARBINARY(16) DEFAULT NULL;

    SELECT id, dsSalt
      INTO v_id, v_salt
    FROM usuarios
    WHERE dsUsuario = _dsUsuario
      AND dsEstado  = '1'
      AND dsPassword = IF(dsSalt IS NULL,
                          UNHEX(SHA2(_dsPassword, 512)),
                          UNHEX(SHA2(CONCAT(dsSalt, _dsPassword), 512)))
    LIMIT 1;

    -- MigraciÃ³n transparente del hash antiguo (sin salt) al nuevo (con salt)
    IF v_id IS NOT NULL AND v_salt IS NULL THEN
        SET v_salt = RANDOM_BYTES(16);
        UPDATE usuarios
           SET dsSalt     = v_salt,
               dsPassword = UNHEX(SHA2(CONCAT(v_salt, _dsPassword), 512))
         WHERE id = v_id;
    END IF;

    -- Si v_id es NULL (credenciales incorrectas) no devuelve filas
    SELECT id, dsId, dsUsuario, dsEstado, idDepartamento,
           dsUsuarioCreacion, dtFechaCreacion
    FROM usuarios
    WHERE id = v_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
